$body = @{ dmnPath = "dinnerDecisions.dmn"; decisionId = "beverages"; inputs = @{ desiredDish = "Stew"; guestsWithChildren = "true" } } | ConvertTo-Json; try { $response = Invoke-RestMethod -Uri "http://localhost:5000/api/dmn/evaluate" -Method POST -ContentType "application/json" -Body $body; Write-Host "Response:"; $response | ConvertTo-Json -Depth 10 } catch { Write-Host "Error: $($_.Exception.Message)" }
